    for (const [project, title] of [[1, 'Plan \t  Release'], [1, 'Other'], [1, 'PLAN release deleted'], [2, 'Plan release second'], [3, 'Plan release archived']]) {
      await checkedPost(`/projects/${project}/tasks`, { title });
